contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 value) public {
        require(to != address(0), "recipient must be nonzero");
        require(value <= c.totalSupply(), "value must not exceed total supply");
        require(to != address(this), "recipient must not be the test contract");

        uint256 senderBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

