            assert(c.balanceOf(address(this)) == senderBefore - value);
            assert(c.balanceOf(to) == recipientBefore + value);
        } else {
            assert(c.balanceOf(address(this)) == senderBefore);
            assert(c.balanceOf(to) == recipientBefore);
        }
