contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public {
        require(amount <= c.totalSupply(), "amount exceeds total supply");

        uint256 totalBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 expectedAfter = totalBefore - amount;

        bool reverted;
        try c.burn(amount) returns (bool success) {
            reverted = !success;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.totalSupply() == expectedAfter && c.balanceOf(address(this)) == balanceBefore - amount);
        } else {
            assert(c.totalSupply() == totalBefore && c.balanceOf(address(this)) == balanceBefore);
        }
    }
}

